import{_ as r,o as a,c as i,a2 as t}from"./chunks/framework.DDk04jjR.js";const g=JSON.parse('{"title":"Уроки","description":"Навчальні матеріали з 3D-моделювання та цифрового виробництва","frontmatter":{"layout":"page","title":"Уроки","description":"Навчальні матеріали з 3D-моделювання та цифрового виробництва"},"headers":[],"relativePath":"solar-system.md","filePath":"solar-system.md"}'),o={name:"solar-system.md"};function l(n,e,d,s,c,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="🎓-уроки" tabindex="-1">🎓 Уроки <a class="header-anchor" href="#🎓-уроки" aria-label="Permalink to &quot;🎓 Уроки&quot;">​</a></h1><p>Ласкаво просимо до розділу навчальних матеріалів! Тут ви знайдете покрокові уроки з 3D-моделювання, проєктування та друку.</p><hr><h2 id="📚-доступні-курси" tabindex="-1">📚 Доступні курси <a class="header-anchor" href="#📚-доступні-курси" aria-label="Permalink to &quot;📚 Доступні курси&quot;">​</a></h2><div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));gap:1.5rem;margin:2rem 0;"><div style="background:linear-gradient(135deg, #eef2ff, #e8e0ff);border-radius:16px;padding:2rem;border:1px solid #e0e0ef;transition:transform 0.2s;"><h3 style="margin-top:0;">🎨 Blender для початківців</h3><p>Перші кроки у світі 3D-моделювання. Інтерфейс, навігація, базові інструменти та створення першої моделі.</p><a href="/3d-lecture/blender-basics" style="display:inline-block;padding:0.5rem 1.2rem;background:linear-gradient(135deg, #6366f1, #8b5cf6);color:white;border-radius:8px;text-decoration:none;font-weight:600;">Почати навчання →</a></div><div style="background:linear-gradient(135deg, #eef2ff, #e8e0ff);border-radius:16px;padding:2rem;border:1px solid #e0e0ef;transition:transform 0.2s;"><h3 style="margin-top:0;">⚙️ Основи Fusion</h3><p>Знайомство з Autodesk Fusion 360 — ескізи, параметричне моделювання та підготовка деталей до виробництва.</p><a href="/3d-lecture/fusion-basics" style="display:inline-block;padding:0.5rem 1.2rem;background:linear-gradient(135deg, #6366f1, #8b5cf6);color:white;border-radius:8px;text-decoration:none;font-weight:600;">Почати навчання →</a></div><div style="background:linear-gradient(135deg, #eef2ff, #e8e0ff);border-radius:16px;padding:2rem;border:1px solid #e0e0ef;transition:transform 0.2s;"><h3 style="margin-top:0;">🖨️ Основи 3D-друку</h3><p>Технології 3D-друку, підготовка моделей у слайсері, налаштування принтера та перший успішний друк.</p><a href="/3d-lecture/3d-print-basics" style="display:inline-block;padding:0.5rem 1.2rem;background:linear-gradient(135deg, #6366f1, #8b5cf6);color:white;border-radius:8px;text-decoration:none;font-weight:600;">Почати навчання →</a></div></div><h3 id="_3-багатошарова-анімація" tabindex="-1">3. Багатошарова анімація <a class="header-anchor" href="#_3-багатошарова-анімація" aria-label="Permalink to &quot;3. Багатошарова анімація&quot;">​</a></h3><ul><li><strong>Орбітальний рух</strong> – планета рухається навколо Сонця</li><li><strong>Осьовий рух</strong> – планета обертається навколо своєї осі</li><li><strong>Побічний рух</strong> – якщо б була Місяць, вона б оберталася навколо планети</li></ul><h3 id="_4-освітлення" tabindex="-1">4. Освітлення <a class="header-anchor" href="#_4-освітлення" aria-label="Permalink to &quot;4. Освітлення&quot;">​</a></h3><p>Вико́ристовуємо кілька типів освітлення:</p><ul><li><code>AmbientLight</code> – рівномірне освітлення сцени</li><li><code>PointLight</code> – світло від Сонця</li></ul><h2 id="вправи" tabindex="-1">Вправи <a class="header-anchor" href="#вправи" aria-label="Permalink to &quot;Вправи&quot;">​</a></h2><p>Спробуйте модифікувати код:</p><ol><li><strong>Змініть кольори</strong> планет</li><li><strong>Добавте нові планети</strong> з власними параметрами</li><li><strong>Змініть швидкість обертання</strong> деяких планет</li><li><strong>Добавте контроль камери</strong> за допомогою миші</li><li><strong>Змініть освітлення</strong> для різних ефектів</li></ol><h2 id="висновки" tabindex="-1">Висновки <a class="header-anchor" href="#висновки" aria-label="Permalink to &quot;Висновки&quot;">​</a></h2><p>Коловий рух у 3D просторі – це простий, але потужний концепт у комп&#39;ютерній графіці. За допомогою параметричних рівнянь та тригонометрії ми можемо створювати плавні, природні анімації.</p><p>Ключові точки:</p><ul><li>📐 Використовуйте <code>Math.cos()</code> та <code>Math.sin()</code> для обчислення позиції</li><li>⚙️ Контролюйте швидкість за допомогою кутової швидкості</li><li>🎨 Комбінуйте різні типи руху для складніших ефектів</li><li>🎬 Анімаційні цикли постійно оновлюють позицію об&#39;єктів</li></ul><h2 id="посилання" tabindex="-1">Посилання <a class="header-anchor" href="#посилання" aria-label="Permalink to &quot;Посилання&quot;">​</a></h2><ul><li><a href="https://threejs.org/docs/" target="_blank" rel="noreferrer">Three.js Документація</a></li><li><a href="https://developer.mozilla.org/uk/docs/Web/JavaScript/Reference/Global_Objects/Math" target="_blank" rel="noreferrer">MDN: Math.cos() та Math.sin()</a></li><li><a href="https://uk.wikipedia.org/wiki/%D0%9F%D0%B0%D1%80%D0%B0%D0%BC%D0%B5%D1%82%D1%80%D0%B8%D1%87%D0%BD%D1%96_%D1%80%D1%96%D0%B2%D0%BD%D1%8F%D0%BD%D0%BD%D1%8F" target="_blank" rel="noreferrer">Параметричні рівняння</a></li></ul>',19)])])}const f=r(o,[["render",l]]);export{g as __pageData,f as default};
